using LibreKO.Common.Domain.Entities.GameData;
using LibreKO.Editors.Contracts;
using LibreKO.Editors.Core.Events;
using LibreKO.Editors.DataHost.Events;
using Microsoft.EntityFrameworkCore;
public class EventWriteTests {
 [Fact] public async Task AllEventFamiliesPersistAndPreserveState(){await EventFixture.Ensure();var j=new TestEventJournal();var service=new EventDatabase(EventFixture.Cs,Path.GetTempPath(),j);
 var race=EventFixture.Race(EventFixture.Id());Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(race.BuildChange(Guid.NewGuid()))).Status);
 var lottery=EventFixture.New(EventFamily.Lottery,EventFixture.Id());var root=EventFixture.Row(EventTable.LotteryEvents,lottery.Original.Key.Id);root["Name"]="Lottery test";EventFixture.Add(lottery,EventTable.LotteryEvents,root);foreach(var table in new[]{EventTable.LotterySchedules,EventTable.LotteryRewards}){var row=EventFixture.Row(table,EventFixture.Id());row["LotteryId"]=lottery.Original.Key.Id;if(table==EventTable.LotteryRewards){row["ItemId"]=123450001;row["Count"]=1;row["Place"]=1;}EventFixture.Add(lottery,table,row);}Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(lottery.BuildChange(Guid.NewGuid()))).Status);
 var temple=new EventDraft((await service.GetAsync(new(EventFamily.Temple,5)))!);foreach(var table in new[]{EventTable.TempleEventSchedules,EventTable.TempleEventRewards,EventTable.ForgottenTempleWaves}){var row=EventFixture.Row(table,EventFixture.Id());if(table==EventTable.ForgottenTempleWaves){row["NpcId"]=880001;row["Count"]=1;row["Tier"]=1;row["Wave"]=1;}else row["Event"]=5;EventFixture.Add(temple,table,row);}Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(temple.BuildChange(Guid.NewGuid()))).Status);
 foreach(var zone in new[]{210,211}){await using(var db=EventFixture.Open()){if(!await db.ZoneInfos.AnyAsync(x=>x.ZoneNo==zone)){db.ZoneInfos.Add(new ZoneInfoData{ZoneNo=(short)zone,MapName="Compound zone"});await db.SaveChangesAsync();}}var d=EventFixture.New(EventFamily.MapEvent,31001,zone);var row=EventFixture.Row(EventTable.GameEvents,31001,zone);row["Type"]=1;row["Exec1"]=210;EventFixture.Add(d,EventTable.GameEvents,row);var existing=await service.GetAsync(d.Original.Key);if(existing!=null){d=new(existing);d.Set(existing.Rows[0].Key,"Exec2",(int.Parse(existing.Rows[0].Values["Exec2"]!.ToString())+1)%100);}Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(d.BuildChange(Guid.NewGuid()))).Status);}
 foreach(var (family,table) in new[]{(EventFamily.MapObject,EventTable.MapObjects),(EventFamily.NpcTrigger,EventTable.EventTriggers)}){var d=EventFixture.New(family,EventFixture.Id());var row=EventFixture.Row(table,d.Original.Key.Id);if(table==EventTable.MapObjects)row["ZoneId"]=210;EventFixture.Add(d,table,row);Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(d.BuildChange(Guid.NewGuid()))).Status);}
 await using(var db=EventFixture.Open()){await db.SiegeWarfare.Where(r=>r.CastleIndex==31001).ExecuteDeleteAsync();db.SiegeWarfare.Add(new SiegeWarfareData{CastleIndex=31001,WarDay=1,MasterKnights=99,MoradonTax=1200,SiegeType=2,ChallengeListStr="preserve",RequestList1=14});await db.SaveChangesAsync();}var siege=new EventDraft((await service.GetAsync(new(EventFamily.CastleSiege,31001)))!);siege.Set(siege.Rows[0].Key,"WarTime",18);await using(var db=EventFixture.Open()){await db.SiegeWarfare.Where(r=>r.CastleIndex==31001).ExecuteUpdateAsync(s=>s.SetProperty(r=>r.MoradonTax,1400).SetProperty(r=>r.MasterKnights,(short)100));}Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(siege.BuildChange(Guid.NewGuid()))).Status);var state=(await service.GetAsync(siege.Original.Key))!.Rows[0].Values;Assert.Equal("1400",state["MoradonTax"]!.ToString());Assert.Equal("100",state["MasterKnights"]!.ToString());Assert.Equal("preserve",state["ChallengeListStr"]!.ToString());Assert.Equal("14",state["RequestList1"]!.ToString());Assert.Equal("2",state["SiegeType"]!.ToString());
 var source=(await service.GetAsync(race.Original.Key))!;var copy=await service.PlanDuplicateAsync(source.Key,EventFixture.Id());Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(copy)).Status);Assert.Equal(source.Version,(await service.GetAsync(source.Key))!.Version);Assert.Equal(4,(await service.GetAsync(copy.Before.Key))!.Rows.Count);Assert.DoesNotContain(copy.Rows,r=>source.Rows.Any(s=>s.Key==r.Key));await Assert.ThrowsAsync<InvalidOperationException>(()=>service.PlanDuplicateAsync(new(EventFamily.Temple,5),7));await Assert.ThrowsAsync<InvalidOperationException>(()=>service.PlanDuplicateAsync(siege.Original.Key,1));
 }
 [Fact] public async Task AtomicChildrenAndStaleMembership(){await EventFixture.Ensure();var j=new TestEventJournal();var service=new EventDatabase(EventFixture.Cs,Path.GetTempPath(),j);var d=EventFixture.Race(EventFixture.Id());var reward=d.Rows.Single(r=>r.Key.Table==EventTable.CollectionRaceRewards);d.Set(reward.Key,"ItemCount",-1);Assert.Equal(SaveStatus.Invalid,(await service.SaveAsync(d.BuildChange(Guid.NewGuid()))).Status);Assert.Equal(0,j.Prepared);Assert.Null(await service.GetAsync(d.Original.Key));d.Set(reward.Key,"ItemCount",1);Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(d.BuildChange(Guid.NewGuid()))).Status);var old=(await service.GetAsync(d.Original.Key))!;var remove=new EventDraft(old);foreach(var row in remove.Rows)remove.Remove(row.Key);await using(var db=EventFixture.Open()){db.CollectionRaceSchedules.Add(new(){Id=EventFixture.Id(),RaceId=old.Key.Id,Hour=3});await db.SaveChangesAsync();}Assert.Equal(SaveStatus.Conflict,(await service.SaveAsync(remove.BuildChange(Guid.NewGuid()))).Status);Assert.Equal(5,(await service.GetAsync(old.Key))!.Rows.Count);var fresh=new EventDraft((await service.GetAsync(old.Key))!);fresh.Set(fresh.Rows.Single(r=>r.Key.Table==EventTable.CollectionRaceRewards).Key,"ItemId",int.MaxValue);Assert.Equal(SaveStatus.Invalid,(await service.SaveAsync(fresh.BuildChange(Guid.NewGuid()))).Status);Assert.Equal("Test race",(await service.GetAsync(old.Key))!.Rows.Single(r=>r.Key.Table==EventTable.CollectionRaces).Values["Name"]!.ToString());
 var collision=EventFixture.Race(old.Key.Id);Assert.Equal(SaveStatus.Conflict,(await service.SaveAsync(collision.BuildChange(Guid.NewGuid()))).Status);var exact=new EventDraft((await service.GetAsync(old.Key))!);foreach(var row in exact.Rows)exact.Remove(row.Key);var deleted=await service.SaveAsync(exact.BuildChange(Guid.NewGuid()));Assert.True(deleted.Status==SaveStatus.Saved,deleted.Message);Assert.Null(await service.GetAsync(old.Key));
 }
 [Fact] public async Task JournalFailureAndUnknownCommitHaveDifferentOutcomes(){await EventFixture.Ensure();var journal=new TestEventJournal{FailPrepare=true};var service=new EventDatabase(EventFixture.Cs,Path.GetTempPath(),journal);var d=EventFixture.Race(EventFixture.Id());Assert.Equal(SaveStatus.Invalid,(await service.SaveAsync(d.BuildChange(Guid.NewGuid()))).Status);Assert.Null(await service.GetAsync(d.Original.Key));journal.FailPrepare=false;journal.FailCommit=true;Assert.Equal(SaveStatus.UnknownCommit,(await service.SaveAsync(d.BuildChange(Guid.NewGuid()))).Status);Assert.NotNull(await service.GetAsync(d.Original.Key));Assert.Equal(0,journal.Aborted);}
 [Fact] public void MapControlTargetIsNotAnNpcPrototype()=>Assert.Null(EventRules.ReferenceFor(EventTable.MapObjects,"ControlNpcId",new(){["Type"]=2}));
}
